from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless row/column permutation optimizer guided by exact serialized-prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store only lightweight metadata and never mutate the supplied dataframe."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Serialize a scalar as the evaluator does, mapping scalar missing values to ''. """
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Find the common-prefix length with logarithmically many C-level slice comparisons."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            mid = (low + high + 1) // 2
            if left[:mid] == right[:mid]:
                low = mid
            else:
                high = mid - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Return exact ideal character-Trie reuse using sorted adjacent serialized rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _group_score(cells, rows, order) -> int:
        """Score one conditional leaf after applying one candidate field ordering."""
        strings = ["".join(cells[r, c] for c in order) for r in rows]
        if len(strings) < 2:
            return 0
        strings.sort()
        return sum(Evolved._lcp(strings[i - 1], strings[i])
                   for i in range(1, len(strings)))

    def _make_strings(self, cells, orders) -> List[str]:
        """Materialize lossless serialized rows for row-specific column permutations."""
        return [
            "".join(cells[r, c] for c in orders[r])
            for r in range(cells.shape[0])
        ]

    def _global_order(self, cells, mode: int) -> List[int]:
        """Build a deterministic global order from length-weighted value repetition."""
        n, m = cells.shape
        ranked = []
        for c in range(m):
            counts = {}
            total_len = 0
            for value in cells[:, c]:
                total_len += len(value)
                counts[value] = counts.get(value, 0) + 1

            repetition = sum(k * (k - 1) for k in counts.values())
            weighted = sum(
                len(value) * k * (k - 1)
                for value, k in counts.items()
            )

            if mode == 0:
                key = weighted
            elif mode == 1:
                key = repetition * max(1, total_len // max(1, n))
            else:
                key = weighted + repetition

            ranked.append((key, c))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [c for _, c in ranked]

    def _refine_leaf(self, cells, rows, order) -> List[int]:
        """Perform two bounded passes of exact adjacent-swap refinement on one leaf."""
        if len(order) < 2 or len(rows) < 2:
            return order

        current = list(order)
        current_score = self._group_score(cells, rows, current)
        limit = min(12, len(current) - 1)

        # Two deterministic passes: forward and backward adjacent comparisons.
        for direction in (1, -1):
            positions = range(limit) if direction == 1 else range(limit - 1, -1, -1)
            for pos in positions:
                trial = current[:]
                trial[pos], trial[pos + 1] = trial[pos + 1], trial[pos]
                trial_score = self._group_score(cells, rows, trial)
                if trial_score > current_score:
                    current = trial
                    current_score = trial_score

        return current

    def _conditional_orders(self, cells) -> List[List[int]]:
        """Partition by one repeated leading field and refine each leaf by exact local swaps."""
        n, m = cells.shape
        if m <= 1:
            return [list(range(m)) for _ in range(n)]

        lead_scores = []
        for c in range(m):
            counts = {}
            for value in cells[:, c]:
                counts[value] = counts.get(value, 0) + 1
            score = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            lead_scores.append((score, c))

        lead = max(lead_scores, key=lambda item: (item[0], -item[1]))[1]

        groups = {}
        for row, value in enumerate(cells[:, lead]):
            groups.setdefault(value, []).append(row)

        remaining = [c for c in range(m) if c != lead]
        result = [None] * n

        for rows in groups.values():
            ranked = []
            for c in remaining:
                counts = {}
                for row in rows:
                    value = cells[row, c]
                    counts[value] = counts.get(value, 0) + 1
                score = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )
                ranked.append((score, c))

            ranked.sort(key=lambda item: (-item[0], item[1]))
            suffix = [c for _, c in ranked]

            # The leading field remains fixed; only the suffix is locally refined.
            suffix = self._refine_leaf(cells, rows, suffix)
            full_order = [lead] + suffix

            for row in rows:
                result[row] = full_order[:]

        return result

    def _candidate(self, cells, orders):
        """Materialize one candidate, score it exactly, and sort rows lexicographically."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(range(len(strings)), key=lambda row: (strings[row], row))
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate bounded global and conditional orders, returning a lossless best permutation."""
        n, m = df.shape
        self.num_rows, self.num_cols = n, m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)
        for r in range(n):
            for c in range(m):
                cells[r, c] = self._cell_text(raw[r, c])

        # Constraints whose detailed merge semantics belong to the parent API are
        # conservatively honored by retaining the source column order.
        constrained = bool(col_merge or one_way_dep or early_stop or
                           row_stop is not None or col_stop is not None)

        if constrained:
            source_order = list(range(m))
            candidates = [[source_order[:] for _ in range(n)]]
        else:
            global_a = self._global_order(cells, 0)
            global_b = self._global_order(cells, 1)
            conditional = self._conditional_orders(cells)
            candidates = [
                [global_a[:] for _ in range(n)],
                [global_b[:] for _ in range(n)],
                conditional,
            ]

        best = None
        for orders in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-column for column in signature))
            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, strings, row_order, orders = best
        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            order = orders[source]
            output[destination, :] = [raw[source, c] for c in order]
            column_orders.append([df.columns[c] for c in order])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders


